WFJ.Data.add("quest", {
  [87288] = { "Pelli morbide di fiera", "Porta $N1 Soft Nightsaber Pelt ad Aldria.", "Salve, <viaggiatore/viaggiatrice>! Spero che la visita al nostro villaggio ti stia piacendo. Mi piace Dolanaar perché è piccolo e rustico, e tutti sono cordiali.\n\nCommercio qui in zona e porto ogni genere di attrezzi e ninnoli che potrebbero esserti utili nei tuoi viaggi. Anzi, se ti interessa uno scambio, mi servirebbero delle pelli di fiera della notte. Queste creature maestose sono bellissime, ma quelle della zona sono piuttosto aggressive, quindi non sentirti troppo in colpa se ti difendi.", "Che bello rivederti! Sei qui per uno scambio?", "Oh, sono splendide. È un peccato ricorrere alla violenza contro animali così maestosi, ma è importante mantenere sicure le strade, e queste pelli diventeranno bellissime coperte e scialli.\n\nEcco, lascia che ti dia qualcosa per ricordarle. È al tempo stesso morbido e robusto.", 0x8e68b306, 0x5828382e, 0x9dca9c14, 0x16c13c9e, 0x8c6d1a47, "....." },
  [87318] = { "Cuori smarriti", "Cerca Essene, la compagna di Corma.", "Il ⟦Thandol Span=Viadotto di Thandol⟧ è un posto pericoloso da quando i Ferroscuro hanno fatto saltare il ponte, ma non mi aspettavo di imbattermi in loro proprio lì!\n\nSono riuscita a fuggire, ma ho perso di vista la mia compagna, Essene. L'ho cercata dappertutto, ma non ho trovato traccia di lei. L'hanno catturata i Ferroscuro? È caduta nel fiume qui sotto? È riuscita a tornare dall'altra parte? Non lo so! Non so nemmeno se sia viva!\n\nTi prego, se trovi qualche traccia di lei, fammelo sapere!", nil, nil, 0xecc2e5e4, 0xdc3f5e49, 0xbcc51c2c, nil, nil, "...mm" },
  [87491] = { "Una scintilla di libertà", "Scorta l'elementale del fuoco prigioniero fuori da Dun Modr, verso la libertà.", "Sss! Gli immondi ⟦Dark Iron=Ferroscuro⟧ mi hanno evocato e mi tengono in gabbia accanto al loro misero focolare!\n\nIl fuoco deve correre selvaggio, correre libero! Liberami! Devo fuggire! Devo BRUCIARE!\n\nNessun ⟦Dark Iron=Ferroscuro⟧ è al sicuro! Raderli al suolo col fuoco! Bruciare la loro polvere nera! Bruciare la loro fortezza, le loro micce, la loro follia!\n\nFammi uscire e li BRUCERÒ TUTTI!", nil, nil, 0x2b274e59, 0x187207a1, 0xa71d7ba7, nil, nil, "...mm" },
  [87760] = { nil, "Trova una Stormscale Beastmistress, uccidila e riporta la sua ⟦Rod of Deep Dominion=Verga del Dominio Profondo⟧.", "Ho ricevuto notizie da Darnassus, {name}!\n\nDai campioni animali abbiamo appreso che i naga hanno soggiogato queste creature marine per usarle come cavalcature e bestie da soma contro la loro volontà. Quelle troppo ostinate, o troppo vecchie o gravemente ferite, le hanno scacciate per divertimento. Mostruoso!\n\nÈ nostro sacro dovere porre fine a tutto questo!\n\nI naga hanno delle forze nelle ⟦Ruins of Mathystra=Rovine di Mathystra⟧, e di certo catturano i plesiosauri al largo della costa. Trova la loro domatrice, uccidila e riporta i suoi strumenti di dominio!", nil, nil, 0xbe769717, 0x6347b42a, 0xeef193cf, nil, nil, "e..mm" },
})
